package net.officefloor.hq.app.paste;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.claim.ClaimService;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The claim paste box of a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/claims/paste")
@Validated
public class PasteController {

    /** The pasted lines of {@code name,amount,date,note}. */
    public record PasteRequest(@NotNull @Size(max = 200_000) String text) {
    }

    /** How many claims were added, and the claims, in the order of their lines. */
    public record PasteView(int added, List<ClaimView> claims) {
    }

    private final PasteService service;
    private final ClaimService claimService;

    public PasteController(PasteService service, ClaimService claimService) {
        this.service = service;
        this.claimService = claimService;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PasteView paste(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PasteRequest request) {
        List<ClaimView> claims = ClaimView.allOf(service.paste(sheetId.trim(), user.trim(), request.text()), claimService);
        return new PasteView(claims.size(), claims);
    }
}
package net.officefloor.hq.app.paste;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** A paste with no lines, or with a line that is not {@code name,amount,date,note} as the claim form
 * takes them. */
@ResponseStatus(HttpStatus.BAD_REQUEST)
public class PasteLineException extends RuntimeException {
}
package net.officefloor.hq.app.paste;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Adds a DRAFT claim per pasted line of {@code name,amount,date,note}, in order, for the person on the
 * sheet with that name (compared as names are). The date may be blank (the sheet's today); the note may
 * hold commas, or be left out. Each line is held to the claim form's rules; it is one change: when any
 * line is refused no claim is added, and nothing is recorded. Blank lines are skipped. A note ending in
 * {@code " #<reference>"} gives the claim that external reference, which is not part of the note. */
@Service
public class PasteService {

    /** An amount as the claim form takes it. */
    private static final Pattern AMOUNT = Pattern.compile("\\s*-?\\d{1,10}(\\.\\d{1,2})?\\s*");

    /** The longest note the claim form takes. */
    private static final int NOTE_MAX = 500;

    /** The longest reference the claim form takes. */
    private static final int REF_MAX = 120;

    private final PersonRepository people;
    private final ClaimService claimService;

    public PasteService(PersonRepository people, ClaimService claimService) {
